-- Recovered from the production migration ledger for deterministic rebuilds.
create or replace function public.tedvio_sync_group_compat() returns trigger language plpgsql set search_path=public as $$ declare p_name text; u_name text; begin select p.name,u.name into p_name,u_name from public.v2_programs p join public.v2_universities u on u.id=p.university_id where p.id=new.program_id; new.group_name:=new.name; new.school_cycle:=new.term; new.program:=coalesce(p_name,new.program); new.university:=coalesce(u_name,new.university); return new; end $$; drop trigger if exists trg_tedvio_sync_group_compat on public.v2_groups; create trigger trg_tedvio_sync_group_compat before insert or update of program_id,name,term on public.v2_groups for each row execute function public.tedvio_sync_group_compat(); create or replace function public.tedvio_sync_program_groups() returns trigger language plpgsql set search_path=public as $$ begin if new.name is distinct from old.name or new.university_id is distinct from old.university_id then update public.v2_groups g set program=new.name, university=u.name from public.v2_universities u where g.program_id=new.id and u.id=new.university_id; end if; return new; end $$; drop trigger if exists trg_tedvio_sync_program_groups on public.v2_programs; create trigger trg_tedvio_sync_program_groups after update of name,university_id on public.v2_programs for each row execute function public.tedvio_sync_program_groups(); create or replace function public.tedvio_sync_university_groups() returns trigger language plpgsql set search_path=public as $$ begin if new.name is distinct from old.name then update public.v2_groups g set university=new.name from public.v2_programs p where g.program_id=p.id and p.university_id=new.id; end if; return new; end $$; drop trigger if exists trg_tedvio_sync_university_groups on public.v2_universities; create trigger trg_tedvio_sync_university_groups after update of name on public.v2_universities for each row execute function public.tedvio_sync_university_groups(); update public.v2_groups g set group_name=g.name,school_cycle=g.term,program=p.name,university=u.name from public.v2_programs p join public.v2_universities u on u.id=p.university_id where g.program_id=p.id;

